# Java: files, serialization and networking (50 problems). Files are made in the working folder and removed at the end; network programs only talk to the local machine (loopback), so every run gives the same output.
IO = "java.io.* java.nio.file.* java.nio.charset.StandardCharsets"
NET = "java.io.* java.net.* java.util.concurrent.*"
SL = [("line", "s")]
T = "File I/O"
LN = "One line of text."
jq("j-io-filewriter", "Write a File with FileWriter", "EASY", T, "Write the line you read into a new file `note.txt` with `FileWriter`. Print `Written: <number of characters>` and `File size: <bytes>` (from `File.length()`). Delete the file at the end.", LN, "Two lines.", "ASCII text up to 100 characters",
   'File f = new File("note.txt");\ntry (FileWriter w = new FileWriter(f)) {\n    w.write(s);\n}\nSystem.out.println("Written: " + s.length());\nSystem.out.println("File size: " + f.length());\nf.delete();', ["hello world", "a", "Next Byte", "12345", "Java I/O"], SL, imports=IO)
jq("j-io-filereader-chars", "Read a File Character by Character", "EASY", T, "Write the line to `chars.txt`, then read it back one character at a time with `FileReader.read()`. Print `Characters: <count>` and `Letters: <count of letters>`. Delete the file.", LN, "Two lines.", "ASCII text up to 100 characters",
   'File f = new File("chars.txt");\ntry (FileWriter w = new FileWriter(f)) {\n    w.write(s);\n}\nint total = 0, letters = 0, ch;\ntry (FileReader r = new FileReader(f)) {\n    while ((ch = r.read()) != -1) {\n        total++;\n        if (Character.isLetter(ch)) letters++;\n    }\n}\nSystem.out.println("Characters: " + total);\nSystem.out.println("Letters: " + letters);\nf.delete();', ["hello world", "a1b2", "Next Byte 2026", "12345", "!! ??"], SL, imports=IO)
jq("j-io-bufferedreader-lines", "Read a File Line by Line", "EASY", T, "Read `n` lines of text, write them to `lines.txt`, then read the file back with `BufferedReader.readLine()` and print each as `<line number>: <text>`. Delete the file.", "First line `n`, then `n` lines.", "`n` lines.", "1 <= n <= 20",
   'int n = Integer.parseInt(in.nextLine().trim());\nFile f = new File("lines.txt");\ntry (PrintWriter w = new PrintWriter(f)) {\n    for (int i = 0; i < n; i++) w.println(in.nextLine());\n}\ntry (BufferedReader r = new BufferedReader(new FileReader(f))) {\n    String line;\n    int k = 1;\n    while ((line = r.readLine()) != null) System.out.println(k++ + ": " + line);\n}\nf.delete();', ["3\nred\ngreen\nblue", "1\nsolo", "2\nhello world\nbye", "4\na\nb\nc\nd", "2\nx y z\n12"], (), imports=IO, scanner=True)
jq("j-io-append", "Append to a File", "EASY", T, "Write the first line to `log.txt`, then **append** the second line with `new FileWriter(file, true)`. Print the file's lines with a `BufferedReader`, each on its own line, and then `Lines: <count>`. Delete the file.", "Two lines of text.", "Three lines.", "ASCII text",
   'String first = in.nextLine(), second = in.nextLine();\nFile f = new File("log.txt");\ntry (FileWriter w = new FileWriter(f)) {\n    w.write(first + "\\n");\n}\ntry (FileWriter w = new FileWriter(f, true)) {\n    w.write(second + "\\n");\n}\nint count = 0;\ntry (BufferedReader r = new BufferedReader(new FileReader(f))) {\n    String line;\n    while ((line = r.readLine()) != null) {\n        System.out.println(line);\n        count++;\n    }\n}\nSystem.out.println("Lines: " + count);\nf.delete();', ["first\nsecond", "a\nb", "hello world\nbye now", "1 2\n3 4", "x\ny"], (), imports=IO, scanner=True)
jq("j-io-count-text", "Count Characters, Words and Lines", "MEDIUM", T, "Read all the lines of the input, save them in `text.txt`, then read the file and print `Lines: <x>`, `Words: <y>` and `Characters: <z>` (characters without the line breaks). Delete the file.", "Any number of lines of text.", "Three lines.", "At most 100 lines",
   'File f = new File("text.txt");\ntry (PrintWriter w = new PrintWriter(f)) {\n    while (in.hasNextLine()) w.println(in.nextLine());\n}\nint lines = 0, words = 0, chars = 0;\ntry (BufferedReader r = new BufferedReader(new FileReader(f))) {\n    String line;\n    while ((line = r.readLine()) != null) {\n        lines++;\n        chars += line.length();\n        if (!line.trim().isEmpty()) words += line.trim().split("\\\\s+").length;\n    }\n}\nSystem.out.println("Lines: " + lines + "\\nWords: " + words + "\\nCharacters: " + chars);\nf.delete();', ["hello world\nbye\n", "one\n", "a b c\nd e\nf\n", "to be or not to be\n", "x\n\ny\n"], (), imports=IO, scanner=True)
jq("j-io-copy-text", "Copy a Text File", "MEDIUM", T, "Write the input lines to `source.txt`, copy it to `copy.txt` character by character, and print `Copied: <number of bytes>` and `Identical: <true/false>` (compare the two files' contents). Delete both files.", "Any number of lines of text.", "Two lines.", "At most 100 lines",
   'File a = new File("source.txt"), b = new File("copy.txt");\ntry (PrintWriter w = new PrintWriter(a)) {\n    while (in.hasNextLine()) w.println(in.nextLine());\n}\ntry (FileReader r = new FileReader(a); FileWriter w = new FileWriter(b)) {\n    int ch;\n    while ((ch = r.read()) != -1) w.write(ch);\n}\nSystem.out.println("Copied: " + b.length());\nSystem.out.println("Identical: " + Arrays.equals(Files.readAllBytes(a.toPath()), Files.readAllBytes(b.toPath())));\na.delete();\nb.delete();', ["hello world\nbye\n", "one\n", "a b c\nd e\nf\n", "to be or not to be\n", "x\n\ny\n"], (), imports=IO, scanner=True)
jq("j-io-search-word", "Search a Word in a File", "MEDIUM", T, "Read a word, then the lines of a text. Save the lines to `search.txt`; read the file back and print the number of every line (starting at 1) that contains the word, each on one line as `Line <k>`; if none contains it print `Not found`. Delete the file.", "First line the word; then any number of text lines.", "The matching lines or `Not found`.", "At most 100 lines",
   'String word = in.nextLine().trim();\nFile f = new File("search.txt");\ntry (PrintWriter w = new PrintWriter(f)) {\n    while (in.hasNextLine()) w.println(in.nextLine());\n}\nboolean found = false;\ntry (BufferedReader r = new BufferedReader(new FileReader(f))) {\n    String line;\n    int k = 0;\n    while ((line = r.readLine()) != null) {\n        k++;\n        if (line.contains(word)) {\n            System.out.println("Line " + k);\n            found = true;\n        }\n    }\n}\nif (!found) System.out.println("Not found");\nf.delete();', ["cat\nthe cat sat\na dog\ncat nap\n", "xyz\nhello\nworld\n", "a\na\nb\na\n", "to\nto be\nor not\nto be\n", "one\none\n"], (), imports=IO, scanner=True)
jq("j-io-reverse-file", "Reverse a File's Lines", "MEDIUM", T, "Save the input lines to `rev.txt`, read them into a list and print them in reverse order, one per line. Delete the file.", "Any number of lines of text.", "The lines in reverse order.", "At most 100 lines",
   'File f = new File("rev.txt");\ntry (PrintWriter w = new PrintWriter(f)) {\n    while (in.hasNextLine()) w.println(in.nextLine());\n}\nList<String> lines = Files.readAllLines(f.toPath());\nCollections.reverse(lines);\nfor (String l : lines) System.out.println(l);\nf.delete();', ["one\ntwo\nthree\n", "solo\n", "a b\nc d\n", "x\n\ny\n", "1\n2\n3\n4\n"], (), imports=IO, scanner=True)
jq("j-io-delete-file", "Delete a File", "EASY", T, "Create `temp.txt`, print `Exists: <true/false>`, delete it with `File.delete()` and print `Deleted: <result>` and `Exists: <true/false>` again.", "There is no input.", "Three lines.", "None.",
   'File f = new File("temp.txt");\nf.createNewFile();\nSystem.out.println("Exists: " + f.exists());\nSystem.out.println("Deleted: " + f.delete());\nSystem.out.println("Exists: " + f.exists());', [""], (), imports=IO, samples=1)
jq("j-io-file-info", "File Information", "MEDIUM", T, "Write the line to `info.txt` and print its `Size: <bytes> bytes`, `Readable: <b>`, `Writable: <b>`, `Is file: <b>`, `Is directory: <b>` and `Modified recently: <true if lastModified is within the last 60 seconds>`. Delete the file.", LN, "Six lines.", "ASCII text up to 100 characters",
   'File f = new File("info.txt");\ntry (FileWriter w = new FileWriter(f)) {\n    w.write(s);\n}\nSystem.out.println("Size: " + f.length() + " bytes");\nSystem.out.println("Readable: " + f.canRead());\nSystem.out.println("Writable: " + f.canWrite());\nSystem.out.println("Is file: " + f.isFile());\nSystem.out.println("Is directory: " + f.isDirectory());\nSystem.out.println("Modified recently: " + (System.currentTimeMillis() - f.lastModified() < 60000));\nf.delete();', ["hello world", "a", "Next Byte", "12345", "Java I/O"], SL, imports=IO)
jq("j-io-list-directory", "List a Directory", "MEDIUM", T, "Make a folder `box`, create inside it the files named on the input (`n` names) and one sub-folder `inner`. Print every entry sorted by name: `file <name>` or `folder <name>`. Then delete everything.", "First line `n`, then `n` file names.", "`n + 1` lines.", "1 <= n <= 10, names are simple words",
   'File dir = new File("box");\ndir.mkdir();\nfor (int i = 0; i < n; i++) new File(dir, w[i]).createNewFile();\nnew File(dir, "inner").mkdir();\nFile[] entries = dir.listFiles();\nArrays.sort(entries);\nfor (File e : entries) System.out.println((e.isDirectory() ? "folder " : "file ") + e.getName());\nfor (File e : entries) e.delete();\ndir.delete();', ["3\nb.txt a.txt c.txt", "1\nsolo.txt", "2\nz.log a.log", "4\nd c b a", "2\nreport notes"], [("words", "n w")], imports=IO)
jq("j-io-mkdirs", "Create Nested Folders", "EASY", T, "Read a path like `a/b/c`. Create all the folders at once with `File.mkdirs()` and print `Created: <true/false>`, `Is directory: <true/false>`. Then delete the folders from the inside out and print `Cleaned: <true/false>` (true when the top folder no longer exists).", "One relative path.", "Three lines.", "At most 5 folder names, letters only",
   'File dir = new File(path);\nSystem.out.println("Created: " + dir.mkdirs());\nSystem.out.println("Is directory: " + dir.isDirectory());\nFile cur = dir;\nwhile (cur != null) {\n    cur.delete();\n    cur = cur.getParentFile();\n}\nSystem.out.println("Cleaned: " + !new File(path.split("/")[0]).exists());', ["a/b/c", "x", "one/two", "p/q/r/s", "dirA/dirB"], [("String", "path")], imports=IO)
jq("j-io-rename-file", "Rename a File", "EASY", T, "Create `old.txt`, rename it to `new.txt` with `renameTo` and print `Renamed: <true/false>`, `old.txt exists: <b>` and `new.txt exists: <b>`. Delete the new file.", "There is no input.", "Three lines.", "None.",
   'File a = new File("old.txt"), b = new File("new.txt");\na.createNewFile();\nSystem.out.println("Renamed: " + a.renameTo(b));\nSystem.out.println("old.txt exists: " + a.exists());\nSystem.out.println("new.txt exists: " + b.exists());\nb.delete();', [""], (), imports=IO, samples=1)
jq("j-io-binary-streams", "Binary Files", "MEDIUM", T, "Write the bytes `0, 1, 2, ..., n-1` (each as `i % 256`) to `data.bin` with `FileOutputStream`, read them back with `FileInputStream` and print `Bytes: <count>` and `Sum: <sum of the bytes read>`. Delete the file.", ONE if False else "One integer `n`.", "Two lines.", "1 <= n <= 5000",
   'File f = new File("data.bin");\ntry (FileOutputStream out = new FileOutputStream(f)) {\n    for (int i = 0; i < n; i++) out.write(i % 256);\n}\nint count = 0;\nlong sum = 0;\ntry (FileInputStream inp = new FileInputStream(f)) {\n    int b;\n    while ((b = inp.read()) != -1) {\n        count++;\n        sum += b;\n    }\n}\nSystem.out.println("Bytes: " + count);\nSystem.out.println("Sum: " + sum);\nf.delete();', ["10", "1", "256", "1000", "5000"], [("int", "n")], imports=IO)
jq("j-io-buffered-copy", "Copy a Binary File with Buffers", "MEDIUM", T, "Create `big.bin` with `k` kilobytes (each byte is `i % 251`), copy it to `big-copy.bin` using `BufferedInputStream` and `BufferedOutputStream` with a 4096-byte buffer, and print `Copied: <bytes> bytes` and `Identical: <true/false>`. Delete both files.", "One integer `k`.", "Two lines.", "1 <= k <= 200",
   'File a = new File("big.bin"), b = new File("big-copy.bin");\ntry (OutputStream out = new BufferedOutputStream(new FileOutputStream(a))) {\n    for (int i = 0; i < k * 1024; i++) out.write(i % 251);\n}\nlong copied = 0;\ntry (InputStream src = new BufferedInputStream(new FileInputStream(a)); OutputStream dst = new BufferedOutputStream(new FileOutputStream(b))) {\n    byte[] buffer = new byte[4096];\n    int read;\n    while ((read = src.read(buffer)) > 0) {\n        dst.write(buffer, 0, read);\n        copied += read;\n    }\n}\nSystem.out.println("Copied: " + copied + " bytes");\nSystem.out.println("Identical: " + Arrays.equals(Files.readAllBytes(a.toPath()), Files.readAllBytes(b.toPath())));\na.delete();\nb.delete();', ["1", "4", "10", "100", "200"], [("int", "k")], imports=IO)
jq("j-io-data-output", "DataOutputStream", "MEDIUM", T, "Read `id name price` and write them to `rec.dat` with `DataOutputStream` (`writeInt`, `writeUTF`, `writeDouble`). Print `File size: <bytes>` (that is `4 + 2 + length of name + 8` for ASCII names). Delete the file.", "One line: `id name price`.", "One line.", "name has no spaces",
   'File f = new File("rec.dat");\ntry (DataOutputStream out = new DataOutputStream(new FileOutputStream(f))) {\n    out.writeInt(id);\n    out.writeUTF(name);\n    out.writeDouble(price);\n}\nSystem.out.println("File size: " + f.length());\nf.delete();', ["1 pen 9.5", "100 notebook 45.25", "7 a 0", "42 laptop 55000.99", "5 ink 120"], [("int", "id"), ("String", "name"), ("double", "price")], imports=IO)
jq("j-io-data-input", "DataInputStream", "MEDIUM", T, "Write `id name price` to a file with `DataOutputStream`, read the values back in the same order with `DataInputStream` and print `Id: <id>`, `Name: <name>` and `Price: <price>` (two decimals). Delete the file.", "One line: `id name price`.", "Three lines.", "name has no spaces",
   'File f = new File("rec2.dat");\ntry (DataOutputStream out = new DataOutputStream(new FileOutputStream(f))) {\n    out.writeInt(id);\n    out.writeUTF(name);\n    out.writeDouble(price);\n}\ntry (DataInputStream inp = new DataInputStream(new FileInputStream(f))) {\n    System.out.println("Id: " + inp.readInt());\n    System.out.println("Name: " + inp.readUTF());\n    System.out.printf("Price: %.2f%n", inp.readDouble());\n}\nf.delete();', ["1 pen 9.5", "100 notebook 45.25", "7 a 0", "42 laptop 55000.99", "5 ink 120"], [("int", "id"), ("String", "name"), ("double", "price")], imports=IO)
jq("j-io-printwriter", "Formatted Output with PrintWriter", "EASY", T, "Read `n` students (`name marks`) and write them to `report.txt` with `PrintWriter.printf` as `<name> ...... <marks>` where the name is padded to 8 characters (`%-8s`) and the marks use 3 digits (`%3d`). Read the file back and print it.", "First line `n`, then `n` lines `name marks`.", "`n` lines.", "1 <= n <= 20",
   'File f = new File("report.txt");\ntry (PrintWriter w = new PrintWriter(f)) {\n    for (int i = 0; i < n; i++) w.printf("%-8s ...... %3d%n", in.next(), in.nextInt());\n}\ntry (BufferedReader r = new BufferedReader(new FileReader(f))) {\n    String line;\n    while ((line = r.readLine()) != null) System.out.println(line);\n}\nf.delete();', ["2\nasha 82\nravi 91", "1\nk 5", "3\nanil 100\nbob 7\ncat 55", "2\nlongername 99\nx 0", "1\nsolo 42"], [("int", "n")], imports=IO)
jq("j-io-scanner-file", "Parse a File with Scanner", "MEDIUM", T, "Read `n` lines `name marks`, save them in `marks.txt`, then parse the **file** with a `Scanner` and print `Average: <average marks>` (two decimals) and `Top: <name of the highest marks>` (the first one on a tie). Delete the file.", "First line `n`, then `n` lines `name marks`.", "Two lines.", "1 <= n <= 50",
   'File f = new File("marks.txt");\ntry (PrintWriter w = new PrintWriter(f)) {\n    for (int i = 0; i < n; i++) w.println(in.next() + " " + in.nextInt());\n}\nint total = 0, best = -1;\nString top = "";\nint count = 0;\ntry (Scanner file = new Scanner(f)) {\n    while (file.hasNext()) {\n        String name = file.next();\n        int marks = file.nextInt();\n        total += marks;\n        count++;\n        if (marks > best) {\n            best = marks;\n            top = name;\n        }\n    }\n}\nSystem.out.printf("Average: %.2f%n", (double) total / count);\nSystem.out.println("Top: " + top);\nf.delete();', ["3\nasha 82\nravi 91\nmeena 77", "1\nk 50", "2\na 60\nb 60", "4\nw 10\nx 20\ny 30\nz 40", "2\nsana 100\nomar 99"], [("int", "n")], imports=IO)
jq("j-io-properties", "Read a .properties File", "MEDIUM", T, "Save the pairs `key=value` you read into `app.properties` using `Properties.store`. Then load the file with `Properties.load` and print the value of the key `lang` (or `Unknown` when it is missing, using `getProperty(key, default)`), and `Keys: <number of keys>`. Delete the file.", "First line `n`, then `n` lines `key value`.", "Two lines.", "1 <= n <= 20",
   'Properties p = new Properties();\nfor (int i = 0; i < n; i++) p.setProperty(in.next(), in.next());\nFile f = new File("app.properties");\ntry (FileWriter w = new FileWriter(f)) {\n    p.store(w, null);\n}\nProperties loaded = new Properties();\ntry (FileReader r = new FileReader(f)) {\n    loaded.load(r);\n}\nSystem.out.println(loaded.getProperty("lang", "Unknown"));\nSystem.out.println("Keys: " + loaded.size());\nf.delete();', ["2\nlang java\nmode dark", "1\ntheme light", "3\nlang python\na 1\nb 2", "2\nx 1\ny 2", "1\nlang c"], [("int", "n")], imports=IO)

T = "Serialization and NIO"
PERSON = 'class Person implements Serializable {\n    private static final long serialVersionUID = 1L;\n    String name;\n    int age;\n    Person(String name, int age) {\n        this.name = name;\n        this.age = age;\n    }\n}'
jq("j-io-serialize", "Serialize an Object", "MEDIUM", T, "`Person` implements `Serializable`. Read `name age`, write the object to `person.ser` with `ObjectOutputStream` and print `Saved: <true if the file is not empty>`. Delete the file.", "One line: `name age`.", "One line.", "name has no spaces",
   'File f = new File("person.ser");\ntry (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(f))) {\n    out.writeObject(new Person(name, age));\n}\nSystem.out.println("Saved: " + (f.length() > 0));\nf.delete();', ["asha 20", "ravi 41", "k 0", "meena 33", "sana 99"], [("String", "name"), ("int", "age")], imports=IO, classes=PERSON)
jq("j-io-deserialize", "Deserialize an Object", "MEDIUM", T, "Write a `Person` to a file with `ObjectOutputStream`, read it back with `ObjectInputStream` and print `Name: <name>` and `Age: <age>` of the restored object. Delete the file.", "One line: `name age`.", "Two lines.", "name has no spaces",
   'File f = new File("person2.ser");\ntry (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(f))) {\n    out.writeObject(new Person(name, age));\n}\ntry (ObjectInputStream inp = new ObjectInputStream(new FileInputStream(f))) {\n    Person p = (Person) inp.readObject();\n    System.out.println("Name: " + p.name);\n    System.out.println("Age: " + p.age);\n}\nf.delete();', ["asha 20", "ravi 41", "k 0", "meena 33", "sana 99"], [("String", "name"), ("int", "age")], imports=IO, classes=PERSON)
jq("j-io-serial-version-uid", "serialVersionUID", "HARD", T, "`serialVersionUID` identifies a version of a class. Without a fixed value, changing the class makes old saved objects unreadable. Give class `Ticket` the fixed id `42L`, then print `UID: <id>` using `ObjectStreamClass.lookup(Ticket.class).getSerialVersionUID()`, and `Round trip: <true/false>` after saving and loading a ticket with the seat number you read.", "One integer: the seat number.", "Two lines.", "0 <= seat <= 1000",
   'System.out.println("UID: " + ObjectStreamClass.lookup(Ticket.class).getSerialVersionUID());\nFile f = new File("ticket.ser");\ntry (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(f))) {\n    out.writeObject(new Ticket(n));\n}\ntry (ObjectInputStream inp = new ObjectInputStream(new FileInputStream(f))) {\n    System.out.println("Round trip: " + (((Ticket) inp.readObject()).seat == n));\n}\nf.delete();', ["12", "0", "1000", "7", "99"], [("int", "n")], imports=IO,
   classes='class Ticket implements Serializable {\n    private static final long serialVersionUID = 42L;\n    int seat;\n    Ticket(int seat) {\n        this.seat = seat;\n    }\n}')
jq("j-io-transient", "The transient Keyword", "MEDIUM", T, "A `transient` field is skipped when an object is saved. `Account` has `name` and a `transient String password`. Save an account (`name password`) and load it back; print `name=<name>` and `password=<password>` of the restored object (the password is lost: `null`).", "One line: `name password`.", "Two lines.", "No spaces",
   'File f = new File("acct.ser");\ntry (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(f))) {\n    out.writeObject(new Account(name, pw));\n}\ntry (ObjectInputStream inp = new ObjectInputStream(new FileInputStream(f))) {\n    Account a = (Account) inp.readObject();\n    System.out.println("name=" + a.name);\n    System.out.println("password=" + a.password);\n}\nf.delete();', ["asha secret", "ravi 1234", "k x", "meena pass", "sana abc"], [("String", "name pw")], imports=IO,
   classes='class Account implements Serializable {\n    private static final long serialVersionUID = 1L;\n    String name;\n    transient String password;\n    Account(String name, String password) {\n        this.name = name;\n        this.password = password;\n    }\n}')
jq("j-io-custom-serialization", "Custom writeObject and readObject", "HARD", T, "Class `Secret` saves its `text` **reversed** by defining private `writeObject` and `readObject` methods (which call `defaultWriteObject`/`defaultReadObject` and handle the field themselves) so a saved file never holds the plain text. Read a word, save and load it and print `Restored: <word>` and `File holds reversed text: <true/false>` (search the bytes of the file for the reversed word).", "One word (at least 2 different letters).", "Two lines.", "At most 20 characters",
   'File f = new File("secret.ser");\ntry (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(f))) {\n    out.writeObject(new Secret(w));\n}\nString raw = new String(Files.readAllBytes(f.toPath()), StandardCharsets.ISO_8859_1);\nString reversed = new StringBuilder(w).reverse().toString();\ntry (ObjectInputStream inp = new ObjectInputStream(new FileInputStream(f))) {\n    System.out.println("Restored: " + ((Secret) inp.readObject()).text);\n}\nSystem.out.println("File holds reversed text: " + raw.contains(reversed));\nf.delete();', ["hello", "abc", "NextByte", "java", "xyz12"], [("String", "w")], imports=IO,
   classes='class Secret implements Serializable {\n    private static final long serialVersionUID = 1L;\n    transient String text;\n    Secret(String text) {\n        this.text = text;\n    }\n    private void writeObject(ObjectOutputStream out) throws IOException {\n        out.defaultWriteObject();\n        out.writeObject(new StringBuilder(text).reverse().toString());\n    }\n    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {\n        in.defaultReadObject();\n        text = new StringBuilder((String) in.readObject()).reverse().toString();\n    }\n}')
jq("j-io-externalizable", "Externalizable", "HARD", T, "With `Externalizable` you write the fields yourself in `writeExternal` and read them in `readExternal` (a public no-argument constructor is required). Save a `Point` with `x y`, load it back and print `Point(<x>, <y>)`.", "One line: `x y`.", "One line.", "|values| <= 1000",
   'File f = new File("point.ser");\ntry (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(f))) {\n    out.writeObject(new Point(x, y));\n}\ntry (ObjectInputStream inp = new ObjectInputStream(new FileInputStream(f))) {\n    Point p = (Point) inp.readObject();\n    System.out.println("Point(" + p.x + ", " + p.y + ")");\n}\nf.delete();', ["1 2", "0 0", "-5 7", "100 -100", "3 3"], [("int", "x y")], imports=IO,
   classes='class Point implements Externalizable {\n    int x, y;\n    public Point() {\n    }\n    Point(int x, int y) {\n        this.x = x;\n        this.y = y;\n    }\n    public void writeExternal(ObjectOutput out) throws IOException {\n        out.writeInt(x);\n        out.writeInt(y);\n    }\n    public void readExternal(ObjectInput in) throws IOException {\n        x = in.readInt();\n        y = in.readInt();\n    }\n}')
jq("j-io-nio-read-all-lines", "Files.readAllLines", "EASY", T, "Write the input lines to `nio.txt` with `Files.write`, then read them with `Files.readAllLines`. Print `Lines: <count>` and `First: <first line>`. Delete the file.", "Any number of lines (at least one).", "Two lines.", "At most 100 lines",
   'Path p = Paths.get("nio.txt");\nList<String> lines = new ArrayList<>();\nwhile (in.hasNextLine()) lines.add(in.nextLine());\nFiles.write(p, lines);\nList<String> back = Files.readAllLines(p);\nSystem.out.println("Lines: " + back.size());\nSystem.out.println("First: " + back.get(0));\nFiles.delete(p);', ["one\ntwo\nthree\n", "solo\n", "a b\nc d\n", "x\n\ny\n", "1\n2\n3\n4\n"], (), imports=IO, scanner=True)
jq("j-io-nio-write", "Files.write", "EASY", T, "Write the string you read to `out.txt` with `Files.write(path, bytes)` and print `Size: <bytes>`. Then append `!` with `StandardOpenOption.APPEND` and print `Size: <bytes>` again. Delete the file.", LN, "Two lines.", "ASCII text up to 100 characters",
   'Path p = Paths.get("out.txt");\nFiles.write(p, s.getBytes(StandardCharsets.UTF_8));\nSystem.out.println("Size: " + Files.size(p));\nFiles.write(p, "!".getBytes(StandardCharsets.UTF_8), StandardOpenOption.APPEND);\nSystem.out.println("Size: " + Files.size(p));\nFiles.delete(p);', ["hello world", "a", "Next Byte", "12345", "Java NIO"], SL, imports=IO)
jq("j-io-nio-copy", "Files.copy", "EASY", T, "Save the line to `src.txt`, copy it with `Files.copy` to `dst.txt` (replacing an existing file) and print `Same content: <true/false>` and `Both exist: <true/false>`. Delete both.", LN, "Two lines.", "ASCII text up to 100 characters",
   'Path a = Paths.get("src.txt"), b = Paths.get("dst.txt");\nFiles.write(a, s.getBytes(StandardCharsets.UTF_8));\nFiles.copy(a, b, StandardCopyOption.REPLACE_EXISTING);\nSystem.out.println("Same content: " + Arrays.equals(Files.readAllBytes(a), Files.readAllBytes(b)));\nSystem.out.println("Both exist: " + (Files.exists(a) && Files.exists(b)));\nFiles.delete(a);\nFiles.delete(b);', ["hello world", "a", "Next Byte", "12345", "Java NIO"], SL, imports=IO)
jq("j-io-nio-walk", "Walk a Directory Tree", "HARD", T, "Make the folder `tree` with the files `a.txt` and `sub/b.txt` and `sub/deep/c.txt` (and the folders in between). Use `Files.walk` to print every **file** path relative to `tree`, using `/`, sorted alphabetically, and `Files: <count>`. Delete the whole tree afterwards.", "There is no input.", "Four lines.", "None.",
   'Path root = Paths.get("tree");\nFiles.createDirectories(root.resolve("sub/deep"));\nFiles.write(root.resolve("a.txt"), "a".getBytes());\nFiles.write(root.resolve("sub/b.txt"), "b".getBytes());\nFiles.write(root.resolve("sub/deep/c.txt"), "c".getBytes());\nList<String> files = new ArrayList<>();\ntry (java.util.stream.Stream<Path> walk = Files.walk(root)) {\n    walk.filter(Files::isRegularFile).forEach(p -> files.add(root.relativize(p).toString().replace(File.separatorChar, \'/\')));\n}\nCollections.sort(files);\nfor (String f : files) System.out.println(f);\nSystem.out.println("Files: " + files.size());\ntry (java.util.stream.Stream<Path> walk = Files.walk(root)) {\n    List<Path> all = new ArrayList<>();\n    walk.forEach(all::add);\n    Collections.reverse(all);\n    for (Path p : all) Files.delete(p);\n}', [""], (), imports=IO, samples=1)
jq("j-io-directory-changes", "Detect Directory Changes", "HARD", T, "Real-time watching (`WatchService`) depends on the operating system, so do the same job by comparing snapshots. Make the folder `watch` with the files named on the first input line, take a snapshot of its names (a `Set`), then create the files named on the second line and delete the ones named on the third; take a second snapshot and print `Created: <sorted names>` and `Deleted: <sorted names>` (`none` when empty). Delete everything at the end.", "Three lines: files that exist at the start, files to create, files to delete (each a space-separated list; a line with just `-` means none).", "Two lines.", "Names are simple words",
   'Path dir = Paths.get("watch");\nFiles.createDirectories(dir);\nString[] start = in.nextLine().trim().split("\\\\s+"), add = in.nextLine().trim().split("\\\\s+"), remove = in.nextLine().trim().split("\\\\s+");\nfor (String n : start) if (!n.equals("-")) Files.write(dir.resolve(n), new byte[0]);\nSet<String> before = new TreeSet<>(Arrays.asList(dir.toFile().list()));\nfor (String n : add) if (!n.equals("-")) Files.write(dir.resolve(n), new byte[0]);\nfor (String n : remove) if (!n.equals("-")) Files.deleteIfExists(dir.resolve(n));\nSet<String> after = new TreeSet<>(Arrays.asList(dir.toFile().list()));\nSet<String> created = new TreeSet<>(after), deleted = new TreeSet<>(before);\ncreated.removeAll(before);\ndeleted.removeAll(after);\nSystem.out.println("Created: " + (created.isEmpty() ? "none" : String.join(" ", created)));\nSystem.out.println("Deleted: " + (deleted.isEmpty() ? "none" : String.join(" ", deleted)));\nfor (File f : dir.toFile().listFiles()) f.delete();\nFiles.delete(dir);', ["a b\nc\nb\n", "x\n-\nx\n", "-\np q\n-\n", "m n o\n-\n-\n", "one two\nthree\ntwo\n"], (), imports=IO, scanner=True)
jq("j-io-file-channel", "FileChannel and ByteBuffer", "HARD", T, "Write the bytes `1..n` to `chan.bin` with a `FileChannel` and a `ByteBuffer`, then read them back into a new buffer. Print `Read: <count> bytes` and `Sum: <sum of the bytes>`. Delete the file.", "One integer `n`.", "Two lines.", "1 <= n <= 100",
   'Path p = Paths.get("chan.bin");\ntry (FileChannel ch = FileChannel.open(p, StandardOpenOption.CREATE, StandardOpenOption.WRITE)) {\n    ByteBuffer buf = ByteBuffer.allocate(n);\n    for (int i = 1; i <= n; i++) buf.put((byte) i);\n    buf.flip();\n    ch.write(buf);\n}\nint sum = 0, count;\ntry (FileChannel ch = FileChannel.open(p, StandardOpenOption.READ)) {\n    ByteBuffer buf = ByteBuffer.allocate(n);\n    count = ch.read(buf);\n    buf.flip();\n    while (buf.hasRemaining()) sum += buf.get();\n}\nSystem.out.println("Read: " + count + " bytes");\nSystem.out.println("Sum: " + sum);\nFiles.delete(p);', ["5", "1", "100", "10", "50"], [("int", "n")], imports=IO + " java.nio.* java.nio.channels.FileChannel")
jq("j-io-mapped-buffer", "Memory-Mapped File", "HARD", T, "Create `map.bin` holding the `int` values `1..n` (4 bytes each). Map the file into memory with `FileChannel.map` and read the values through the `MappedByteBuffer`'s `IntBuffer` view. Print `Count: <n>` and `Last: <last value>`. Delete the file.", "One integer `n`.", "Two lines.", "1 <= n <= 1000",
   'Path p = Paths.get("map.bin");\nByteBuffer w = ByteBuffer.allocate(n * 4);\nfor (int i = 1; i <= n; i++) w.putInt(i);\nFiles.write(p, w.array());\ntry (FileChannel ch = FileChannel.open(p, StandardOpenOption.READ)) {\n    MappedByteBuffer mb = ch.map(FileChannel.MapMode.READ_ONLY, 0, ch.size());\n    IntBuffer ints = mb.asIntBuffer();\n    System.out.println("Count: " + ints.limit());\n    System.out.println("Last: " + ints.get(ints.limit() - 1));\n}\nFiles.delete(p);', ["5", "1", "100", "1000", "10"], [("int", "n")], imports=IO + " java.nio.* java.nio.channels.FileChannel")
jq("j-io-zip", "Create a ZIP Archive", "MEDIUM", T, "Put the text you read into a ZIP file `data.zip` as one entry called `note.txt` with `ZipOutputStream`. Then open the archive with `ZipFile` and print `Entries: <count>`, `Entry: <name>` and `Size: <uncompressed size>`. Delete the file.", LN, "Three lines.", "ASCII text up to 100 characters",
   'File f = new File("data.zip");\ntry (ZipOutputStream out = new ZipOutputStream(new FileOutputStream(f))) {\n    out.putNextEntry(new ZipEntry("note.txt"));\n    out.write(s.getBytes(StandardCharsets.UTF_8));\n    out.closeEntry();\n}\ntry (ZipFile zip = new ZipFile(f)) {\n    System.out.println("Entries: " + zip.size());\n    ZipEntry e = zip.entries().nextElement();\n    System.out.println("Entry: " + e.getName());\n    System.out.println("Size: " + e.getSize());\n}\nf.delete();', ["hello world", "a", "Next Byte", "12345", "zip me"], SL, imports=IO + " java.util.zip.*")
jq("j-io-unzip", "Extract a ZIP Archive", "MEDIUM", T, "Create a ZIP with the text as an entry `note.txt`, then read it back with `ZipInputStream` and print `Extracted <name>: <text>`. Delete the file.", LN, "One line.", "ASCII text up to 100 characters",
   'File f = new File("unzip.zip");\ntry (ZipOutputStream out = new ZipOutputStream(new FileOutputStream(f))) {\n    out.putNextEntry(new ZipEntry("note.txt"));\n    out.write(s.getBytes(StandardCharsets.UTF_8));\n    out.closeEntry();\n}\ntry (ZipInputStream zin = new ZipInputStream(new FileInputStream(f))) {\n    ZipEntry e = zin.getNextEntry();\n    ByteArrayOutputStream buf = new ByteArrayOutputStream();\n    byte[] chunk = new byte[256];\n    int read;\n    while ((read = zin.read(chunk)) > 0) buf.write(chunk, 0, read);\n    System.out.println("Extracted " + e.getName() + ": " + new String(buf.toByteArray(), StandardCharsets.UTF_8));\n}\nf.delete();', ["hello world", "a", "Next Byte", "12345", "zip me"], SL, imports=IO + " java.util.zip.*")

T = "Networking"
jq("j-net-tcp-echo-server", "A TCP Echo Server", "HARD", T, "Start a `ServerSocket` on a free port (`new ServerSocket(0)`). A server thread accepts one connection, reads one line and replies with that line in capitals. In `main` act as the client: connect to `localhost`, send the word and print `Server echoed: <reply>`. Only the local machine is used.", "One word.", "One line.", "No spaces",
   'ServerSocket server = new ServerSocket(0);\nThread t = new Thread(() -> {\n    try (Socket s = server.accept();\n         BufferedReader r = new BufferedReader(new InputStreamReader(s.getInputStream()));\n         PrintWriter w = new PrintWriter(s.getOutputStream(), true)) {\n        w.println(r.readLine().toUpperCase());\n    } catch (IOException e) {\n    }\n});\nt.start();\ntry (Socket c = new Socket("127.0.0.1", server.getLocalPort());\n     PrintWriter w = new PrintWriter(c.getOutputStream(), true);\n     BufferedReader r = new BufferedReader(new InputStreamReader(c.getInputStream()))) {\n    w.println(word);\n    System.out.println("Server echoed: " + r.readLine());\n}\nt.join();\nserver.close();', ["hello", "java", "x", "NextByte", "Echo1"], [("String", "word")], imports=NET)
jq("j-net-tcp-client", "A TCP Client", "HARD", T, "Write `static String ask(int port, String message)` that connects to a server on `localhost`, sends the message as one line and returns the reply line. A small server (already written for you in the program) answers `Echo: <message>` to every line. Read a message and print `Client received: <reply>`.", "One word.", "One line.", "No spaces",
   'ServerSocket server = new ServerSocket(0);\nThread t = new Thread(() -> {\n    try (Socket s = server.accept();\n         BufferedReader r = new BufferedReader(new InputStreamReader(s.getInputStream()));\n         PrintWriter w = new PrintWriter(s.getOutputStream(), true)) {\n        w.println("Echo: " + r.readLine());\n    } catch (IOException e) {\n    }\n});\nt.start();\nSystem.out.println("Client received: " + ask(server.getLocalPort(), word));\nt.join();\nserver.close();', ["hello", "java", "x", "NextByte", "ping"], [("String", "word")], imports=NET,
   members='static String ask(int port, String message) throws IOException {\n    try (Socket c = new Socket("127.0.0.1", port);\n         PrintWriter w = new PrintWriter(c.getOutputStream(), true);\n         BufferedReader r = new BufferedReader(new InputStreamReader(c.getInputStream()))) {\n        w.println(message);\n        return r.readLine();\n    }\n}')
jq("j-net-chat-server", "A Multi-Client Chat Server", "HARD", T, "The server accepts `n` clients, each in its own thread, and stores the line each client sends. `n` client threads connect and send the messages you read. After all of them finish print `Server received <n> messages` and then the messages sorted alphabetically, one per line.", "First line `n`, then `n` words.", "`n + 1` lines.", "1 <= n <= 8",
   'ServerSocket server = new ServerSocket(0);\nList<String> received = Collections.synchronizedList(new ArrayList<>());\nThread acceptor = new Thread(() -> {\n    List<Thread> handlers = new ArrayList<>();\n    try {\n        for (int i = 0; i < n; i++) {\n            Socket s = server.accept();\n            Thread h = new Thread(() -> {\n                try (s; BufferedReader r = new BufferedReader(new InputStreamReader(s.getInputStream()))) {\n                    received.add(r.readLine());\n                } catch (IOException e) {\n                }\n            });\n            h.start();\n            handlers.add(h);\n        }\n        for (Thread h : handlers) h.join();\n    } catch (Exception e) {\n    }\n});\nacceptor.start();\nThread[] clients = new Thread[n];\nfor (int i = 0; i < n; i++) {\n    final String msg = w[i];\n    clients[i] = new Thread(() -> {\n        try (Socket c = new Socket("127.0.0.1", server.getLocalPort());\n             PrintWriter out = new PrintWriter(c.getOutputStream(), true)) {\n            out.println(msg);\n        } catch (IOException e) {\n        }\n    });\n    clients[i].start();\n}\nfor (Thread c : clients) c.join();\nacceptor.join();\nserver.close();\nCollections.sort(received);\nSystem.out.println("Server received " + received.size() + " messages");\nfor (String m : received) System.out.println(m);', ["3\nbeta alpha gamma", "1\nhello", "2\nb a", "4\nd c b a", "2\nx y"], [("words", "n w")], imports=NET)
jq("j-net-chat-client", "A Chat Client", "HARD", T, "A server thread answers every line a client sends with `OK <line>` and stops when it reads `bye`. The client sends the `n` words you read, then `bye`, and prints every answer it receives, one per line, followed by `Disconnected`.", "First line `n`, then `n` words (none is `bye`).", "`n + 1` lines.", "1 <= n <= 10",
   'ServerSocket server = new ServerSocket(0);\nThread t = new Thread(() -> {\n    try (Socket s = server.accept();\n         BufferedReader r = new BufferedReader(new InputStreamReader(s.getInputStream()));\n         PrintWriter out = new PrintWriter(s.getOutputStream(), true)) {\n        String line;\n        while ((line = r.readLine()) != null && !line.equals("bye")) out.println("OK " + line);\n    } catch (IOException e) {\n    }\n});\nt.start();\ntry (Socket c = new Socket("127.0.0.1", server.getLocalPort());\n     PrintWriter out = new PrintWriter(c.getOutputStream(), true);\n     BufferedReader r = new BufferedReader(new InputStreamReader(c.getInputStream()))) {\n    for (String x : w) {\n        out.println(x);\n        System.out.println(r.readLine());\n    }\n    out.println("bye");\n}\nt.join();\nserver.close();\nSystem.out.println("Disconnected");', ["3\nhi there java", "1\nhello", "2\na b", "4\nw x y z", "2\nping pong"], [("words", "n w")], imports=NET)
jq("j-net-http-server", "A Basic HTTP Server", "HARD", T, "Start `com.sun.net.httpserver.HttpServer` on a free port with one handler at `/hello` that answers `Hello, <name>!` (the name comes from the query `?name=...`). Request it with `HttpURLConnection` and print `Status: <code>` and `Body: <text>`. Stop the server.", "One word: the name.", "Two lines.", "No spaces",
   'HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);\nserver.createContext("/hello", ex -> {\n    String q = ex.getRequestURI().getQuery();\n    String who = q != null && q.startsWith("name=") ? q.substring(5) : "stranger";\n    byte[] body = ("Hello, " + who + "!").getBytes(StandardCharsets.UTF_8);\n    ex.sendResponseHeaders(200, body.length);\n    try (OutputStream o = ex.getResponseBody()) {\n        o.write(body);\n    }\n});\nserver.start();\nURL url = new URL("http://127.0.0.1:" + server.getAddress().getPort() + "/hello?name=" + name);\nHttpURLConnection conn = (HttpURLConnection) url.openConnection();\nSystem.out.println("Status: " + conn.getResponseCode());\ntry (BufferedReader r = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {\n    System.out.println("Body: " + r.readLine());\n}\nserver.stop(0);', ["asha", "java", "x", "World", "Next"], [("String", "name")], imports=NET + " com.sun.net.httpserver.HttpServer java.nio.charset.StandardCharsets")
jq("j-net-fetch-html", "Fetch a Web Page", "HARD", T, "A tiny local web server serves an HTML page whose `<title>` is the text you read. Fetch the page with `HttpURLConnection`, read all of it and print `Status: <code>`, `Length: <number of characters>` and `Title: <text between <title> and </title>>`.", "One line of text for the title (no `<`).", "Three lines.", "At most 50 characters",
   'String html = "<html><head><title>" + s + "</title></head><body>Hi</body></html>";\nHttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);\nserver.createContext("/", ex -> {\n    byte[] body = html.getBytes(StandardCharsets.UTF_8);\n    ex.getResponseHeaders().add("Content-Type", "text/html");\n    ex.sendResponseHeaders(200, body.length);\n    try (OutputStream o = ex.getResponseBody()) {\n        o.write(body);\n    }\n});\nserver.start();\nHttpURLConnection conn = (HttpURLConnection) new URL("http://127.0.0.1:" + server.getAddress().getPort() + "/").openConnection();\nint status = conn.getResponseCode();\nStringBuilder sb = new StringBuilder();\ntry (BufferedReader r = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {\n    int ch;\n    while ((ch = r.read()) != -1) sb.append((char) ch);\n}\nString page = sb.toString();\nSystem.out.println("Status: " + status);\nSystem.out.println("Length: " + page.length());\nSystem.out.println("Title: " + page.substring(page.indexOf("<title>") + 7, page.indexOf("</title>")));\nserver.stop(0);', ["My Page", "Hello", "Next Byte Home", "a", "Java Networking"], SL, imports=NET + " com.sun.net.httpserver.HttpServer java.nio.charset.StandardCharsets", scanner=True)
jq("j-net-download-file", "Download a File from a URL", "HARD", T, "A local server serves `k` kilobytes of data (byte `i` is `i % 251`) at `/file`. Download it with `URL.openStream()`, count the bytes and add them up. Print `Downloaded: <bytes> bytes` and `Checksum: <sum of all bytes>`.", "One integer `k`.", "Two lines.", "1 <= k <= 100",
   'byte[] data = new byte[k * 1024];\nfor (int i = 0; i < data.length; i++) data[i] = (byte) (i % 251);\nHttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);\nserver.createContext("/file", ex -> {\n    ex.sendResponseHeaders(200, data.length);\n    try (OutputStream o = ex.getResponseBody()) {\n        o.write(data);\n    }\n});\nserver.start();\nlong total = 0, sum = 0;\ntry (InputStream in2 = new URL("http://127.0.0.1:" + server.getAddress().getPort() + "/file").openStream()) {\n    int b;\n    while ((b = in2.read()) != -1) {\n        total++;\n        sum += b;\n    }\n}\nSystem.out.println("Downloaded: " + total + " bytes");\nSystem.out.println("Checksum: " + sum);\nserver.stop(0);', ["1", "4", "10", "50", "100"], [("int", "k")], imports=NET + " com.sun.net.httpserver.HttpServer")
jq("j-net-udp-server", "A UDP Echo Server", "HARD", T, "A server thread waits on a `DatagramSocket` (free port), receives one packet and sends back the text in capitals. In `main` send the word you read in a `DatagramPacket` and print `Server got: <word>` (printed by the server thread) after the reply has been received.", "One word.", "One line.", "No spaces",
   'DatagramSocket serverSocket = new DatagramSocket(0, InetAddress.getByName("127.0.0.1"));\nString[] got = new String[1];\nThread t = new Thread(() -> {\n    try {\n        byte[] buf = new byte[256];\n        DatagramPacket p = new DatagramPacket(buf, buf.length);\n        serverSocket.receive(p);\n        got[0] = new String(p.getData(), 0, p.getLength(), StandardCharsets.UTF_8);\n        byte[] reply = got[0].toUpperCase().getBytes(StandardCharsets.UTF_8);\n        serverSocket.send(new DatagramPacket(reply, reply.length, p.getAddress(), p.getPort()));\n    } catch (IOException e) {\n    }\n});\nt.start();\ntry (DatagramSocket client = new DatagramSocket()) {\n    byte[] out = word.getBytes(StandardCharsets.UTF_8);\n    client.send(new DatagramPacket(out, out.length, InetAddress.getByName("127.0.0.1"), serverSocket.getLocalPort()));\n    client.setSoTimeout(5000);\n    DatagramPacket in2 = new DatagramPacket(new byte[256], 256);\n    client.receive(in2);\n}\nt.join();\nSystem.out.println("Server got: " + got[0]);\nserverSocket.close();', ["hello", "java", "x", "NextByte", "udp1"], [("String", "word")], imports=NET + " java.nio.charset.StandardCharsets")
jq("j-net-udp-client", "A UDP Client", "HARD", T, "Write `static String send(int port, String text)` that sends the text in a `DatagramPacket` to a server on `localhost` and returns the reply text. The server (provided) answers `Echo: <text>`. Print `Reply: <reply>` for the word you read.", "One word.", "One line.", "No spaces",
   'DatagramSocket server = new DatagramSocket(0, InetAddress.getByName("127.0.0.1"));\nThread t = new Thread(() -> {\n    try {\n        DatagramPacket p = new DatagramPacket(new byte[256], 256);\n        server.receive(p);\n        byte[] reply = ("Echo: " + new String(p.getData(), 0, p.getLength(), StandardCharsets.UTF_8)).getBytes(StandardCharsets.UTF_8);\n        server.send(new DatagramPacket(reply, reply.length, p.getAddress(), p.getPort()));\n    } catch (IOException e) {\n    }\n});\nt.start();\nSystem.out.println("Reply: " + send(server.getLocalPort(), word));\nt.join();\nserver.close();', ["hello", "java", "x", "NextByte", "udp1"], [("String", "word")], imports=NET + " java.nio.charset.StandardCharsets",
   members='static String send(int port, String text) throws IOException {\n    try (DatagramSocket s = new DatagramSocket()) {\n        byte[] out = text.getBytes(StandardCharsets.UTF_8);\n        s.send(new DatagramPacket(out, out.length, InetAddress.getByName("127.0.0.1"), port));\n        s.setSoTimeout(5000);\n        DatagramPacket p = new DatagramPacket(new byte[256], 256);\n        s.receive(p);\n        return new String(p.getData(), 0, p.getLength(), StandardCharsets.UTF_8);\n    }\n}')
jq("j-net-inet-address", "InetAddress", "EASY", T, "Look up the loopback address by its numeric form. Print `Address: <getHostAddress()>`, `Loopback: <isLoopbackAddress()>` and `Bytes: <the four address bytes as numbers 0-255 separated by dots>` for `127.0.0.1`. (Only numeric addresses are used, so no name server is needed.)", "There is no input.", "Three lines.", "None.",
   'InetAddress a = InetAddress.getByName("127.0.0.1");\nSystem.out.println("Address: " + a.getHostAddress());\nSystem.out.println("Loopback: " + a.isLoopbackAddress());\nbyte[] b = a.getAddress();\nSystem.out.println("Bytes: " + (b[0] & 255) + "." + (b[1] & 255) + "." + (b[2] & 255) + "." + (b[3] & 255));', [""], (), imports="java.net.*", samples=1)
jq("j-net-port-scanner", "A Port Scanner", "HARD", T, "Open `k` server sockets on free ports, then scan these ports plus one port you bound and closed again. For each port try `new Socket()` with `connect(..., 300 ms)`; a successful connect means open. Print `Open: <count>` and `Closed: <count>`.", "One integer `k`.", "Two lines.", "1 <= k <= 5",
   'List<ServerSocket> servers = new ArrayList<>();\nList<Integer> ports = new ArrayList<>();\nfor (int i = 0; i < n; i++) {\n    ServerSocket s = new ServerSocket(0);\n    servers.add(s);\n    ports.add(s.getLocalPort());\n}\nServerSocket temp = new ServerSocket(0);\nports.add(temp.getLocalPort());\ntemp.close();\nint open = 0, closed = 0;\nfor (int port : ports) {\n    try (Socket s = new Socket()) {\n        s.connect(new InetSocketAddress("127.0.0.1", port), 300);\n        open++;\n    } catch (IOException e) {\n        closed++;\n    }\n}\nSystem.out.println("Open: " + open);\nSystem.out.println("Closed: " + closed);\nfor (ServerSocket s : servers) s.close();', ["1", "3", "5", "2", "4"], [("int", "n")], imports=NET)
jq("j-net-reachability", "Is a Host Reachable?", "EASY", T, "Check whether the local machine answers: `InetAddress.getByName(\"127.0.0.1\").isReachable(1000)`. Print `Reachable: <true/false>` and `Timeout used: 1000 ms`.", "There is no input.", "Two lines.", "None.",
   'boolean ok = InetAddress.getByName("127.0.0.1").isReachable(1000);\nSystem.out.println("Reachable: " + ok);\nSystem.out.println("Timeout used: 1000 ms");', [""], (), imports="java.net.*", samples=1)
jq("j-net-dns-lookup", "A DNS Lookup Utility", "MEDIUM", T, "A real DNS query needs the internet, so build the utility around a small hosts table: `localhost` -> `127.0.0.1`, `example` -> `93.184.216.34`, `router` -> `192.168.0.1`. Look up the names you read; print `<name> -> <address>` (use `InetAddress.getByAddress` to validate the numbers) or `<name> -> not found`.", "First line `n`, then `n` names.", "`n` lines.", "1 <= n <= 20",
   'Map<String, byte[]> table = new HashMap<>();\ntable.put("localhost", new byte[] {127, 0, 0, 1});\ntable.put("example", new byte[] {(byte) 93, (byte) 184, (byte) 216, 34});\ntable.put("router", new byte[] {(byte) 192, (byte) 168, 0, 1});\nfor (String host : w) {\n    byte[] raw = table.get(host);\n    System.out.println(host + " -> " + (raw == null ? "not found" : InetAddress.getByAddress(raw).getHostAddress()));\n}', ["2\nlocalhost router", "1\nunknown", "3\nexample nope localhost", "1\nrouter", "2\nx example"], [("words", "n w")], imports="java.net.*")
jq("j-net-email-simulation", "Send an Email (Simulation)", "MEDIUM", T, "Sending real mail needs a server, so simulate the JavaMail design: an interface `MailTransport` with `send(Message)`, a `Message` (from, to, subject, body) and a `FakeTransport` that stores sent messages. Read `to subject` and send one message from `noreply@campus.test`; print `Sent to <to>: <subject>` and `Outbox size: <n>`.", "One line: `to subject` (no spaces inside words).", "Two lines.", "No spaces in words",
   'FakeTransport transport = new FakeTransport();\nMessage m = new Message("noreply@campus.test", to, subject, "Hello!");\ntransport.send(m);\nSystem.out.println("Sent to " + transport.outbox.get(0).to + ": " + transport.outbox.get(0).subject);\nSystem.out.println("Outbox size: " + transport.outbox.size());', ["asha@x.com Welcome", "ravi@y.org Reminder", "k@z.in Hi", "me@a.b Report", "sana@s.com Invoice"], [("String", "to subject")],
   classes='class Message {\n    String from, to, subject, body;\n    Message(String from, String to, String subject, String body) {\n        this.from = from;\n        this.to = to;\n        this.subject = subject;\n        this.body = body;\n    }\n}\n\ninterface MailTransport {\n    void send(Message m);\n}\n\nclass FakeTransport implements MailTransport {\n    List<Message> outbox = new ArrayList<>();\n    public void send(Message m) {\n        outbox.add(m);\n    }\n}')
jq("j-net-secure-simulation", "A Secure Connection (Simulation)", "HARD", T, "A real SSL/TLS handshake needs certificates, so simulate the idea of a secure channel: client and server share a secret; the client sends `message` together with its `HmacSHA256` signature; the server recomputes the signature and accepts only if they match. Read `secret message tamper` (`tamper` is `yes` or `no`; `yes` changes the message after signing). Print `Handshake OK`, then `Verified: <true/false>`.", "One line: `secret message tamper`.", "Two lines.", "No spaces in words",
   'String sig = hmac(secret, message);\nString received = tamper.equals("yes") ? message + "!" : message;\nSystem.out.println("Handshake OK");\nSystem.out.println("Verified: " + hmac(secret, received).equals(sig));', ["key hello no", "key hello yes", "s3cret data no", "abc msg yes", "k x no"], [("String", "secret message tamper")], imports="javax.crypto.Mac javax.crypto.spec.SecretKeySpec java.nio.charset.StandardCharsets",
   members='static String hmac(String secret, String text) throws Exception {\n    Mac mac = Mac.getInstance("HmacSHA256");\n    mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));\n    StringBuilder sb = new StringBuilder();\n    for (byte b : mac.doFinal(text.getBytes(StandardCharsets.UTF_8))) sb.append(String.format("%02x", b));\n    return sb.toString();\n}')
